//! End-to-end check of the AI integration path with a real ONNX model.
//!
//! `tests/fixtures/contract-model` is an UNTRAINED network (random weights,
//! generated by `ml/make_fixture_model.py`) that implements the model
//! contract. Its outputs mean nothing; what this test proves is that a model
//! folder is discovered, validated, loaded into ONNX Runtime, run on a stored
//! image, and interpreted — probabilities, verdict and CAM — exactly as a
//! trained model would be.

use std::path::{Path, PathBuf};

use image::{DynamicImage, GrayImage, Luma};
use neuroscan_core::ai::{self, CheckStatus, ModelState};
use neuroscan_core::imaging::decode::{self, ImageFormat};
use neuroscan_core::imaging::ImageLocation;

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/contract-model")
}

fn synthetic_slice(dir: &Path) -> PathBuf {
    // A bright disc on a dark background, roughly the shape of an axial slice.
    let image = GrayImage::from_fn(256, 256, |x, y| {
        let (dx, dy) = (x as f32 - 128.0, y as f32 - 128.0);
        let r = (dx * dx + dy * dy).sqrt();
        Luma([if r < 100.0 { (180.0 - r) as u8 } else { 8 }])
    });
    let path = dir.join("slice.png");
    std::fs::write(
        &path,
        decode::encode_png(DynamicImage::ImageLuma8(image)).unwrap(),
    )
    .unwrap();
    path
}

#[test]
fn fixture_model_validates_loads_and_runs() {
    let (service, status) = ai::load_directory(&fixture_dir());
    assert_eq!(status.state, ModelState::Ready, "{status:#?}");
    assert_eq!(status.checks.len(), 8);
    assert!(
        status
            .checks
            .iter()
            .all(|check| matches!(check.status, CheckStatus::Passed)),
        "{:#?}",
        status.checks
    );
    let info = status.model.expect("model info");
    assert!(info.fixture, "the fixture must announce itself as such");
    assert!(info.sha256_declared);
    assert_eq!((info.input_width, info.input_height), (224, 224));

    let dir = tempfile::tempdir().unwrap();
    let path = synthetic_slice(dir.path());
    let location = ImageLocation {
        id: "img".into(),
        exam_id: "exam".into(),
        path,
        format: ImageFormat::Png,
        frame_index: 0,
        window_center: 127.5,
        window_width: 255.0,
        invert: false,
        width: 256,
        height: 256,
        original_name: "slice.png".into(),
        sha256: String::new(),
    };

    let first = service.analyze(&location).expect("inference");
    let probability = first.interpretation.probability;
    assert!((0.0..=1.0).contains(&probability));
    let total: f64 = first
        .interpretation
        .classes
        .iter()
        .map(|c| c.probability)
        .sum();
    assert!(
        (total - 1.0).abs() < 1e-6,
        "softmax must sum to 1, got {total}"
    );
    assert_eq!(first.preprocessing.input_width, 224);
    assert!(first.model.fixture);

    let map = first
        .activation
        .as_ref()
        .expect("the fixture produces a CAM");
    assert_eq!((map.width, map.height), (7, 7));
    assert!(map.values.iter().all(|v| (0.0..=1.0).contains(v)));
    assert!(
        map.values.iter().any(|v| *v > 0.99),
        "CAM is min-max normalised"
    );

    // Deterministic: the same image gives the same result.
    let second = service.analyze(&location).expect("inference");
    assert!((second.interpretation.probability - probability).abs() < 1e-9);
}

#[test]
fn tampered_model_is_rejected() {
    let dir = tempfile::tempdir().unwrap();
    for name in ["run-config.json", "neuroscan.onnx"] {
        std::fs::copy(fixture_dir().join(name), dir.path().join(name)).unwrap();
    }
    let mut bytes = std::fs::read(dir.path().join("neuroscan.onnx")).unwrap();
    let last = bytes.len() - 1;
    bytes[last] ^= 0xFF;
    std::fs::write(dir.path().join("neuroscan.onnx"), bytes).unwrap();

    let (service, status) = ai::load_directory(dir.path());
    assert_eq!(status.state, ModelState::Error);
    let integrity = status.checks.iter().find(|c| c.id == "integrity").unwrap();
    assert!(matches!(integrity.status, CheckStatus::Failed));
    assert!(!service.is_ready());
}
